#include <string.h>

int main(void) {
    char *name = malloc(8);
    strcpy(name, "alice");
    char *alias = name;       /* a second pointer to the same block */
    free(name);               /* block goes back to the allocator */
    char *other = malloc(8);  /* allocator may reuse that block */
    strcpy(other, "mallory");
    printf("%s\n", alias);    /* use after free: undefined behavior */
    free(other);
    return 0;
}

fn main() {
    let name = String::from("alice");
    let alias = &name;     // borrow
    drop(name);            // try to free while borrowed
    println!("{alias}");
