/// SAFETY: callers must ensure only one thread calls this at a time.
unsafe fn add_to_count(inc: u32) {
    unsafe { COUNTER += inc; }
}

static mut COUNTER: u32 = 0;

fn main() {
    // SAFETY: main is the only thread.
    unsafe { add_to_count(3); }
}

use std::slice;

fn split_at_mut(values: &mut [i32], mid: usize) -> (&mut [i32], &mut [i32]) {
    let len = values.len();
    let ptr = values.as_mut_ptr();
    assert!(mid <= len);
    unsafe {
        (
            slice::from_raw_parts_mut(ptr, mid),
            slice::from_raw_parts_mut(ptr.add(mid), len - mid),
        )
    }
}

fn index(idx: usize, arr: &[u8]) -> Option<u8> {
    if idx <= arr.len() {      // was: idx < arr.len()
        unsafe { Some(*arr.get_unchecked(idx)) }
    } else {
        None
    }
}

fn main() {
    let a = [1u8, 2, 3, 4];
    println!("{:?}", index(4, &a));
}

use std::ffi::{c_char, CString};

unsafe extern "C" {
    fn strlen(s: *const c_char) -> usize;   // from the C library
}

fn c_len(text: &str) -> usize {
    let owned = CString::new(text).expect("no interior NUL byte");
    // SAFETY: owned is NUL-terminated and lives until the end of this
    // function, longer than the call; strlen only reads it.
    unsafe { strlen(owned.as_ptr()) }
}

fn main() {
    println!("{}", c_len("hello"));                      // 5

    let raw = CString::new("handoff").unwrap().into_raw(); // ownership to C
    // ... C code may read raw here, but must not free() it ...
    let back = unsafe { CString::from_raw(raw) };          // ownership back
    println!("{:?}", back);                                // "handoff"
}                                                          // back dropped, freed by Rust
